INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_prir-5-ryby_0','Čím dýchají ryby?',ARRAY['kůží jen','plícemi','nosem','žábrami']::TEXT[],3,'Žábry odebírají kyslík z vody.',1,ARRAY[]::TEXT[],NULL,0,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_1','Čím je pokryté tělo většiny ryb?',ARRAY['šupinami','ostny','peřím','srstí']::TEXT[],0,'Ryby mají šupiny.',1,ARRAY[]::TEXT[],NULL,1,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_2','Čím se ryba pohybuje ve vodě?',ARRAY['ploutvemi a ocasem','nohama','křídly','kopyty']::TEXT[],0,'Ploutve řídí pohyb.',1,ARRAY[]::TEXT[],NULL,2,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_3','Jak se jmenuje vajíčko ryby?',ARRAY['vejce se skořápkou','jikra','mléčí','larva']::TEXT[],1,'Jikry kladou samice.',2,ARRAY[]::TEXT[],NULL,3,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_4','K čemu slouží postranní čára?',ARRAY['k dýchání','k vnímání proudění a pohybů ve vodě','k rozmnožování','k trávení']::TEXT[],1,'Je to smyslový orgán.',2,ARRAY[]::TEXT[],NULL,4,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_5','Která ryba patří mezi dravé ryby?',ARRAY['cejn','plotice','štika','kapr']::TEXT[],2,'Štika loví jiné ryby.',2,ARRAY[]::TEXT[],NULL,5,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_6','Která ryba žije v čistých horských potocích?',ARRAY['kapr','lín','cejn','pstruh']::TEXT[],3,'Pstruh potřebuje čistou studenou vodu.',3,ARRAY[]::TEXT[],NULL,6,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_7','K čemu slouží plynový měchýř?',ARRAY['k udržování polohy ve vodě','k dýchání','k trávení','k rozmnožování']::TEXT[],0,'Plynový měchýř reguluje vznášení.',3,ARRAY[]::TEXT[],NULL,7,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_8','Která ryba se vypravuje k rozmnožování do Sargasového moře?',ARRAY['kapr','štika','pstruh','úhoř']::TEXT[],3,'Úhoř říční.',3,ARRAY[]::TEXT[],NULL,8,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_9','Které ryby mají kostru z chrupavky?',ARRAY['pstruh a okoun','kapr a štika','úhoř a lín','žraloci a rejnoci']::TEXT[],3,'Žraloci mají chrupavčitou kostru.',4,ARRAY[]::TEXT[],NULL,9,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_10','Která ryba je největší mořská ryba?',ARRAY['žralok obrovský (velrybí)','treska','tuňák','makrela']::TEXT[],0,'Žralok obrovský.',4,ARRAY[]::TEXT[],NULL,10,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_11','Jak se nazývá hromadné snášení jiker?',ARRAY['hnízdění','tření','pelichání','línání']::TEXT[],1,'Ryby se v době tření shromažďují.',4,ARRAY[]::TEXT[],NULL,11,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_12','Proč mají ryby tělo vřetenovitého tvaru?',ARRAY['snadněji plavou ve vodě','lépe hrabou','lépe létají','lépe běhají']::TEXT[],0,'Tvar snižuje odpor vody.',5,ARRAY[]::TEXT[],NULL,12,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_13','Co ohrožuje ryby v našich řekách?',ARRAY['kluzký písek','příliš sněhu','moc slunce','znečištění vody a jezy']::TEXT[],3,'Znečištění a překážky brání rybám.',5,ARRAY[]::TEXT[],NULL,13,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-ryby_14','Která ryba bývá vánoční?',ARRAY['úhoř','pstruh','štika','kapr']::TEXT[],3,'Vánoční kapr.',5,ARRAY[]::TEXT[],NULL,14,'c_prir-5-ryby',NULL,NOW()),
('q_prir-5-hlodavci-selmy_0','Který savec patří mezi hlodavce?',ARRAY['liška','vlk','veverka','medvěd']::TEXT[],2,'Veverka má hlodavé zuby.',1,ARRAY[]::TEXT[],NULL,0,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_1','Který savec patří mezi šelmy?',ARRAY['veverka','myš','zajíc','vlk']::TEXT[],3,'Vlk je šelma.',1,ARRAY[]::TEXT[],NULL,1,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_2','Čím jsou hlodavci typičtí?',ARRAY['parohy','kopyty','dlouhými hlodavými řezáky','křídly']::TEXT[],2,'Hlodavci mají stále dorůstající řezáky.',1,ARRAY[]::TEXT[],NULL,2,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_3','Který hlodavec stavěl hráze?',ARRAY['myš','bobr','potkan','veverka']::TEXT[],1,'Bobr evropský.',2,ARRAY[]::TEXT[],NULL,3,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_4','Které zvíře je největší naše šelma?',ARRAY['kuna','medvěd hnědý','liška','rys']::TEXT[],1,'Medvěd hnědý žije v Karpatech.',2,ARRAY[]::TEXT[],NULL,4,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_5','Která šelma je u nás vzácná a má střapce na uších?',ARRAY['kuna','vlk','liška','rys ostrovid']::TEXT[],3,'Rys má štětičky na uších.',2,ARRAY[]::TEXT[],NULL,5,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_6','Který hlodavec dělá zimní zásoby oříšků?',ARRAY['zajíc','veverka','bobr','ondatra']::TEXT[],1,'Veverka zahrabává zásoby.',3,ARRAY[]::TEXT[],NULL,6,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_7','Co jsou špičáky u šelem?',ARRAY['zuby k drcení zrní','zuby k trhání masa','zuby k hlodání','zuby k žvýkání trávy']::TEXT[],1,'Špičáky trhají maso.',3,ARRAY[]::TEXT[],NULL,7,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_8','Která šelma má nejlepší čich a loví ve smečce?',ARRAY['rys','vlk','kuna','jezevec']::TEXT[],1,'Vlci loví ve smečkách.',3,ARRAY[]::TEXT[],NULL,8,'c_prir-5-hlodavci-selmy',NULL,NOW()),
('q_prir-5-hlodavci-selmy_9','Který hlodavec byl zavlečen do našich vod a je nepůvodní?',ARRAY['hryzec','veverka obecná','bobr evropský','ondatra pižmová']::TEXT[],3,'Ondatra je nepůvodní.',4,ARRAY[]::TEXT[],NULL,9,'c_prir-5-hlodavci-selmy',NULL,NOW()),
